import { useState } from 'react'
import { Seg } from '../ui'
// Generated by apps/bench/bench/report.mjs from the raw runs. Never edit numbers by hand.
import summary from '../../../bench/bench/summary.json'

type Stat = { median: number; p25: number; p75: number; n: number } | null
type Cell = { browser: string; net: string; file: string; contender: string; version: string } & Record<Metric, Stat>
type Metric = 'firstBars' | 'complete' | 'peakMemoryMB' | 'tbt'

const cells = summary.cells as unknown as Cell[]

const WHO = [
  { key: 'sillon', name: 'sillon' },
  { key: 'ws', name: 'wavesurfer.js' },
  { key: 'ws-peaks', name: 'wavesurfer.js, peaks made ahead' },
] as const

const FILES: Record<string, string> = { d30s: '30 seconds', d5m: '5 minutes', d1h: '1 hour', d3h: '3 hours' }
const BROWSERS: Record<string, string> = { chromium: 'Chromium', firefox: 'Firefox', webkit: 'WebKit' }
const NETS: Record<string, string> = { local: 'Local', '50mbps': '50 Mbps', '10mbps': '10 Mbps' }

const time = (v: number) => (v < 1000 ? `${Math.round(v)} ms` : `${(v / 1000).toFixed(1)} s`)
const size = (v: number) => (v < 1024 ? `${Math.round(v)} MB` : `${(v / 1024).toFixed(1)} GB`)

const METRICS: { key: Metric; label: string; title: string; unit: (v: number) => string }[] = [
  { key: 'firstBars', label: 'First bars', title: 'First bars on screen', unit: time },
  { key: 'complete', label: 'Whole waveform', title: 'Whole waveform on screen', unit: time },
  { key: 'peakMemoryMB', label: 'Memory', title: 'Most memory used while loading', unit: size },
  { key: 'tbt', label: 'Page blocked', title: 'Time the page could not respond', unit: time },
]

const present = <K extends keyof Cell>(k: K, filter: (c: Cell) => boolean = () => true) =>
  [...new Set(cells.filter(filter).map((c) => c[k] as string))]

function Chart({ rows, metric }: { rows: Cell[]; metric: (typeof METRICS)[number] }) {
  const files = Object.keys(FILES).filter((f) => rows.some((c) => c.file === f))
  return (
    <figure className="chart">
      <figcaption>
        <span className="chart-title">{metric.title}</span>
        <span className="meta">Lower is better</span>
      </figcaption>
      {files.map((file) => {
        const group = WHO.map((w) => ({ ...w, s: rows.find((c) => c.file === file && c.contender === w.key)?.[metric.key] ?? null }))
        // Each file has its own scale: a 3-hour file and a 30-second one don't share an axis.
        const max = Math.max(...group.map((g) => g.s?.median ?? 0)) || 1
        return (
          <div className="chart-group" key={file}>
            <div className="chart-file meta">{FILES[file]}</div>
            {group.map((g) => g.s && (
              <div className="chart-row" key={g.key} tabIndex={0} aria-label={`${g.name}, ${FILES[file]}: ${metric.unit(g.s.median)}`}>
                <span className="chart-who meta">{g.name}</span>
                <div className="chart-track">
                  <div className={`chart-bar ${g.key}`} style={{ width: `max(3px, ${((g.s.median / max) * 100).toFixed(2)}%)` }} />
                  <span className="chart-value">{metric.unit(g.s.median)}</span>
                </div>
                <span className="chart-tip meta" role="tooltip">
                  <b>{metric.unit(g.s.median)}</b> typical · middle half {metric.unit(g.s.p25)} to {metric.unit(g.s.p75)} · {g.s.n} runs
                </span>
              </div>
            ))}
          </div>
        )
      })}
    </figure>
  )
}

function Table({ rows }: { rows: Cell[] }) {
  const files = Object.keys(FILES).filter((f) => rows.some((c) => c.file === f))
  return (
    <div className="bench-table-wrap">
      <table className="bench-table">
        <thead>
          <tr><th>File</th><th>Library</th>{METRICS.map((m) => <th key={m.key}>{m.label}</th>)}</tr>
        </thead>
        <tbody>
          {files.flatMap((file) => WHO.map((w, i) => {
            const c = rows.find((x) => x.file === file && x.contender === w.key)
            return c && (
              <tr key={file + w.key}>
                <td>{i === 0 ? FILES[file] : ''}</td>
                <td>{w.name}</td>
                {METRICS.map((m) => <td key={m.key}>{c[m.key] ? m.unit(c[m.key]!.median) : '–'}</td>)}
              </tr>
            )
          }))}
        </tbody>
      </table>
    </div>
  )
}

export function Bench() {
  const browsers = present('browser')
  const [browser, setBrowser] = useState(browsers[0])
  const nets = present('net', (c) => c.browser === browser)
  const [netChoice, setNet] = useState('local')
  const net = nets.includes(netChoice) ? netChoice : nets[0]
  const [metric, setMetric] = useState<Metric>('firstBars')
  const [view, setView] = useState<'chart' | 'table'>('chart')
  const rows = cells.filter((c) => c.browser === browser && c.net === net && c.file in FILES)
  const runs = rows.filter((c) => c.firstBars).map((c) => c.firstBars!.n)
  const env = summary.env
  return (
    <section id="performance">
      <div className="lede">
        <h2>Performance</h2>
        <p>Compared with wavesurfer.js on the same files. sillon shows its first bars sooner and uses far less memory; on long files, drawing the whole waveform takes it longer. Peaks computed ahead of time on a server are faster than either.</p>
      </div>
      <div className="bench-head">
        <div className="bench-filters">
          {browsers.length > 1 && <Seg label="Browser" value={browser} onChange={setBrowser} options={browsers.map((b) => ({ value: b, label: BROWSERS[b] ?? b }))} small />}
          {nets.length > 1 && <Seg label="Network" value={net} onChange={setNet} options={nets.map((n) => ({ value: n, label: NETS[n] ?? n }))} small />}
        </div>
        <Seg label="Show as" value={view} onChange={setView} options={[{ value: 'chart', label: 'Chart' }, { value: 'table', label: 'Table' }]} small />
      </div>
      {view === 'chart' ? (
        <>
          <div className="bench-metric">
            <Seg label="Measure" value={metric} onChange={setMetric} options={METRICS.map((m) => ({ value: m.key, label: m.label }))} />
          </div>
          <div className="legend meta">
            {WHO.map((w) => <span key={w.key}><i className={`swatch ${w.key}`} />{w.name}</span>)}
          </div>
          <Chart rows={rows} metric={METRICS.find((m) => m.key === metric)!} />
        </>
      ) : (
        <Table rows={rows} />
      )}
      <p className="meta bench-env">
        {env.cpu} · {BROWSERS[browser] ?? browser} {rows[0]?.version} · typical of {Math.min(...runs)}–{Math.max(...runs)} runs each · {summary.power} · {summary.date}
      </p>
      <details className="credit bench-method">
        <summary>How this was measured</summary>
        <ul>
          <li>Every run opens a fresh browser with nothing cached, and the runs are shuffled so no library always goes first.</li>
          <li>Times count from opening the page, so loading each library's code is included. For sillon that includes React.</li>
          <li>Memory is everything the browser used while loading, minus what it uses for an empty page.</li>
          <li>sillon's first bars are the start of a waveform that fills in from left to right. The others draw everything at once, so for them both times are the same.</li>
          <li>Every waveform is checked against ffmpeg's reading of the same file. sillon's matches it. wavesurfer.js by default works from a lower-quality copy of the audio, a difference you can't see at this size.</li>
          <li>The files are spoken word, MP3 at 128 kbps. Peaks made ahead are what wavesurfer.js suggests for long files; making them took a server {time(summary.serverPeaksCost.d1h.serverDecodeMs)} for the hour-long file, which isn't counted above.</li>
        </ul>
      </details>
    </section>
  )
}
